// Disagreements are listed first and separately: agreements confirm the model is
// already fine and teach nothing, so burying the disagreements among them wastes
// the context window on examples that cannot change any rule.
const MAX_AGREEMENTS_SHOWN = 20;

return $input.all().map(item => {
  const row = item.json || {};
  const examples = Array.isArray(row.examples) ? row.examples : [];

  const disagreements = examples.filter(e => e.model !== e.human);
  const agreements = examples.filter(e => e.model === e.human).slice(0, MAX_AGREEMENTS_SHOWN);

  const fmt = e => {
    const note = e.note ? ` | reviewer said: ${e.note}` : '';
    return `- "${e.text}" | model said ${e.model} | correct label ${e.human}${note}`;
  };

  const promptParts = [
    `Client: ${row.client_name}`,
    `Current cheat sheet (version ${row.current_version}):`,
    row.current_rules ? row.current_rules : '(none yet)',
    '',
    `The model got these ${disagreements.length} replies WRONG. These are what you must fix:`,
    disagreements.length ? disagreements.map(fmt).join('\n') : '(none)',
    '',
    `For contrast, these it got right (sample of ${agreements.length}). Do not break them:`,
    agreements.length ? agreements.map(fmt).join('\n') : '(none)',
  ];

  return {
    json: {
      client_id: row.client_id,
      client_name: row.client_name,
      current_version: row.current_version,
      label_count: row.label_count,
      disagreement_count: row.disagreement_count,
      labels_from: row.labels_from,
      labels_to: row.labels_to,
      chat_ids: Array.isArray(row.chat_ids) ? row.chat_ids : [],
      text: promptParts.join('\n'),
    },
  };
});

// The OpenAI node replaces the item, so client context is zipped back on by index.
const prompts = $('Build Generator Prompt').all();
const outputs = $('Generate Cheat Sheet Draft').all();

function parseModelJson(item) {
  const candidates = [
    item.json?.output?.[0]?.content?.[0]?.text,
    item.json?.output,
    item.json?.text,
  ];
  for (const candidate of candidates) {
    let value = candidate;
    if (typeof value === 'string') {
      try { value = JSON.parse(value); } catch { continue; }
    }
    if (value && typeof value.rules_text === 'string') return value;
  }
  throw new Error('Cheat sheet generator returned no rules_text.');
}

return outputs.map((out, index) => {
  const context = prompts[index]?.json || {};
  const parsed = parseModelJson(out);
  const rulesText = parsed.rules_text.trim();

  // Storing an empty sheet would quietly blank the client's rules on activation.
  if (!rulesText) {
    throw new Error(`Empty rules_text generated for client ${context.client_id}.`);
  }

  return {
    json: {
      ...context,
      rules_text: rulesText,
      changes: String(parsed.changes || '').trim(),
    },
  };
});

// One Telegram message per (client, recipient). The Activate button is the human
// gate: an auto-generated prompt must never reach live labelling unread.
const drafts = $('Store Draft Cheat Sheet').all();
const contexts = $('Parse Draft').all();

function escapeHtml(value) {
  return String(value == null ? '' : value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

const messages = [];

drafts.forEach((draftItem, index) => {
  const draft = draftItem.json || {};
  const context = contexts[index]?.json || {};
  const chatIds = Array.isArray(context.chat_ids) ? context.chat_ids : [];

  const message = [
    '<b>Sentiment Cheat Sheet - draft for review</b>',
    '',
    `Client: ${escapeHtml(context.client_name)}`,
    `Draft version: ${draft.version} (current active: v${context.current_version})`,
    `Built from ${context.label_count} labelled replies, ${context.disagreement_count} of which the model got wrong.`,
    '',
    '<b>What changed</b>',
    escapeHtml(context.changes) || '(the generator did not say)',
    '',
    '<b>Proposed rules</b>',
    `<pre>${escapeHtml(context.rules_text)}</pre>`,
    '',
    'This draft is NOT live. Nothing changes until you activate it.',
  ].join('\n');

  for (const chatId of chatIds) {
    messages.push({
      json: {
        chat_id: chatId,
        message,
        draft_id: draft.draft_id,
        activate_button_text: `Activate v${draft.version}`,
        activate_callback_data: `cheatsheet_activate:${draft.draft_id}`,
        discard_button_text: 'Discard',
        discard_callback_data: `cheatsheet_discard:${draft.draft_id}`,
      },
    });
  }
});

return messages;
